tter-spacing: 1px;\n            text-shadow: 0 2px 10px rgba(0, 0, 0, 0.2);\n            /* Deep shadow text */\n            font-family: 'Segoe UI', sans-serif;\n            text-transform: uppercase;\n        }\n\n        /* Content */\n        .content {\n            padding: 40px;\n            background-color: #FFFFFF;\n        }\n\n        h1,\n        h2,\n        h3 {\n            margin-top: 0;\n            color: #0F172A;\n            /* Slate 900 */\n            letter-spacing: -0.5px;\n        }\n\n        p {\n            margin-bottom: 24px;\n            color: #475569;\n            /* Slate 600 */\n            font-size: 16px;\n        }\n\n        /* Glass Button V3 */\n        .btn {\n            display: inline-block;\n            /* Matching Blue Gradient */\n            background: linear-gradient(to right, #2563EB, #0EA5E9);\n            color: #FFFFFF !important;\n            font-weight: 700;\n            text-decoration: none;\n            padding: 14px 40px;\n            border-radius: 50px;\n            text-align: center;\n            margin: 15px 0 35px;\n            /* Glossy reflection shadow */\n            box-shadow: 0 10px 20px -10px rgba(37, 99, 235, 0.5), inset 0 2px 0 rgba(255, 255, 255, 0.2);\n            border: 1px solid rgba(255, 255, 255, 0.1);\n        }\n\n        .btn:hover {\n            transform: translateY(-1px);\n            box-shadow: 0 6px 8px -1px rgba(79, 70, 229, 0.4);\n        }\n\n        .divider {\n            height: 1px;\n            background: linear-gradient(to right, transparent, #E2E8F0, transparent);\n            margin: 30px 0;\n            border: none;\n        }\n\n        /* Glass Highlight Box */\n        .highlight-box {\n            background-color: #F8FAFC;\n            border: 1px solid #E2E8F0;\n            border-radius: 12px;\n            padding: 24px;\n            margin: 24px 0;\n            /* Subtle inner shadow for depth */\n            box-shadow: inset 0 2px 4px 0 rgba(0, 0, 0,